// The investigations report (src/data/investigations.json): 24 PSI combustion investigations
// scored and summarised by Claude from the passages the project's own corpus returned, plus a
// synthesis across them. The file is generated by the team's report tool
// (`pnpm report investigations`); nothing here rewrites it. Every statement carries its sources, and the view shows them all.
//
// The types below are the fields the view renders, not the whole file: the app ships a slim copy
// with only these (see slim.ts). Reading a new field means adding it here and in slim.ts.

import type { Habitat, Pillar } from "../api/types";

/** A statement and the numbered sources of its investigation that back it. */
export interface Cited {
  text: string;
  sources: number[];
}

/** One numbered source of an investigation: a corpus document, never a file URL. */
export interface Source {
  n: number;
  /** Ready-made citation in the team format. */
  label: string;
  /** PSI investigation page, for PSI documents. */
  investigation_url: string | null;
  /** Public NASA page, for non-PSI resources. */
  public_url: string | null;
}

export type CriterionKey =
  | "fire_safety_directness"
  | "habitat_relevance"
  | "predictive_modeling_data"
  | "controls_and_equipment"
  | "earth_applications";

export interface Score {
  /** 0 to 3. */
  score: number;
  reason: string;
  sources?: number[];
  /** True when the code computed it from other scores (habitat_relevance). */
  computed?: boolean;
}

export interface Profile {
  hardware: Cited | null;
  flight_platform: Cited | null;
  dates: Cited | null;
  fuels: Cited | null;
  fuel_type: { value: string; sources: number[] } | null;
  sample_shape_size: Cited | null;
  oxygen: Cited | null;
  pressure: Cited | null;
  airflow: Cited | null;
  variables: Cited[];
  constants: Cited[];
  sensors: Cited[];
  measurements: Cited[];
}

export interface Investigation {
  rank: number;
  accession: string;
  acronym: string | null;
  title: string;
  investigation_url: string;
  /** Weighted total, 0 to 100. */
  total: number;
  evidence_coverage: { card_only: boolean };
  summary: { plain: Cited; technical: Cited };
  scores: Record<CriterionKey, Score>;
  habitats: Record<Habitat, Score>;
  contributions: Record<string, Cited | null>;
  pillars: Partial<Record<Pillar, Cited>>;
  profile: Profile;
  data_for_modeling: (Cited & { readiness?: string }) | null;
  key_findings: Cited[];
  limitations: Cited[];
  sources: Source[];
}

/** A statement of the synthesis and the investigations it is about. */
export interface Linked {
  text: string;
  accessions: string[];
}

export interface HardwareGroup {
  name: string;
  hardware: string;
  accessions: string[];
  similarities: Linked[];
  differences: Linked[];
}

export interface InvestigationsReport {
  run: { generated_at: string; model: string };
  rubric: {
    max_score: number;
    criteria: { key: CriterionKey; weight: number }[];
  };
  investigations: Investigation[];
  habitat_top: Record<Habitat, { accession: string }[]>;
  /** Per pillar and habitat: the investigations that cover it, best first. */
  coverage: Record<Pillar, Record<Habitat, string[]>>;
  synthesis: { overview: Linked; hardware_groups: HardwareGroup[]; gaps: Linked[] };
}

