/** The acronym when PSI gives one, else the accession: "FLEX", "PSI-62". */
export function shortName(inv: Pick<Investigation, "acronym" | "accession">): string {
  return inv.acronym?.trim() || inv.accession;
}

export interface ListFilter {
  habitat?: Habitat;
  pillar?: Pillar;
}

/**
 * The ranking as shown. A pillar keeps the investigations that report on it. A habitat orders
 * by that habitat's score first; ties, and the list without a habitat, keep the report's rank.
 */
export function listed(investigations: Investigation[], filter: ListFilter): Investigation[] {
  const { habitat, pillar } = filter;
  const kept = pillar ? investigations.filter((i) => i.pillars[pillar]) : [...investigations];
  return kept.sort((a, b) => {
    const byHabitat = habitat ? b.habitats[habitat].score - a.habitats[habitat].score : 0;
    return byHabitat || a.rank - b.rank;
  });
}

/**
 * The investigations that cover a pillar: for one habitat as the report lists them, for all
 * habitats every one that covers it somewhere, in the report's rank order.
 */
export function coverageFor(
  report: InvestigationsReport,
  pillar: Pillar,
  habitat: Habitat | undefined,
): string[] {
  const byHabitat = report.coverage[pillar];
  if (habitat) return byHabitat[habitat] ?? [];
  const any = new Set(HABITATS.flatMap((h) => byHabitat[h] ?? []));
  return report.investigations.filter((i) => any.has(i.accession)).map((i) => i.accession);
}

/** An http(s) page for a source: the PSI investigation page, else the public NASA page. */
export function sourceHref(
  source: Pick<Source, "investigation_url" | "public_url">,
): string | null {
  for (const url of [source.investigation_url, source.public_url]) {
    if (!url) continue;
    try {
      const { protocol } = new URL(url);
      if (protocol === "https:" || protocol === "http:") return url;
    } catch {
      // not a URL: never linked
    }
  }
  return null;
}

/** The id of a source inside its investigation's panel, the target of a [n] marker. */
export function sourceId(accession: string, n: number): string {
  return `src-${accession}-${n}`;
}

/** "15 November 2026" from the report's timestamp; the raw text when it is not a date. */
export function reportDate(iso: string): string {
  const date = new Date(iso);
  if (Number.isNaN(date.getTime())) return iso;
  return date.toLocaleDateString("en-GB", {
    day: "numeric",
    month: "long",
    year: "numeric",
    timeZone: "UTC",
  });
}
